INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30101, 'គណនា \(\lim_{x\to 2}\left(3 x^{2} - x + 1\right)\)។', NULL, '["\\(15\\)", "\\(13\\)", "\\(9\\)", "\\(11\\)"]', 3, NULL, 1, 'mcq', 'ដោយ \(f(x)=3x^2-x+1\) ជាពហុធា គេជំនួស \(x=2\) ត្រង់ៗ ៖ \(3(4)-2+1=11\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
