INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30102, 'គណនា \(\lim_{x\to 0}\dfrac{\sin{\left(x \right)}}{x}\) (ក្រាបនៃ \(y=\dfrac{\sin x}{x}\) ដូចក្នុងរូប)។', 'g12sc-cdbeb7c56e.svg', '["\\(+\\infty\\)", "\\(1\\)", "\\(-1\\)", "\\(0\\)"]', 1, NULL, 1, 'mcq', 'លីមីតគោលនៃអនុគមន៍ត្រីកោណមាត្រ ៖ \(\displaystyle\lim_{x\to0}\dfrac{\sin x}{x}=1\) ដោយ \(x\) ជារ៉ាដ្យង់។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30103, 'គណនា \(\lim_{x\to 0}\dfrac{e^{x} - 1}{x}\)។', NULL, '["\\(1\\)", "\\(e\\)", "\\(+\\infty\\)", "\\(0\\)"]', 0, NULL, 1, 'mcq', 'លីមីតគោលនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល ៖ \(\displaystyle\lim_{x\to0}\dfrac{e^x-1}{x}=1\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30104, 'គណនា \(\lim_{x\to 3}\dfrac{x^{2} - 9}{x - 3}\)។', NULL, '["\\(6\\)", "\\(9\\)", "\\(0\\)", "\\(3\\)"]', 0, NULL, 1, 'mcq', 'រាងមិនកំណត់ \(\tfrac00\) ៖ \(\dfrac{(x-3)(x+3)}{x-3}=x+3\) ចំពោះ \(x\ne3\) ដូច្នេះលីមីត \(=6\)។', 'លីមីតរាងមិនកំណត់', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30105, 'គេមាន \(f(x)=2x+1\) និង \(g(x)=x^2\)។ អនុគមន៍បណ្ដាក់ \((g\circ f)(x)=g[f(x)]\) ស្មើនឹងអ្វី ?', NULL, '["\\(2x^2+1\\)", "\\((2x+1)^2\\)", "\\(4x^2+1\\)", "\\(2x+1+x^2\\)"]', 1, NULL, 1, 'mcq', '\((g\circ f)(x)=g[f(x)]=g(2x+1)=(2x+1)^2\)។ អនុគមន៍ \(f\circ g\) ទើបស្មើ \(2x^2+1\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30106, 'គណនា \(\lim_{x\to -\infty}\left(3 + \dfrac{5}{x}\right)\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(8\\)", "\\(5\\)"]', 1, NULL, 1, 'mcq', '\(\dfrac5x\to0\) កាលណា \(x\to-\infty\) ដូច្នេះលីមីត \(=3+0=3\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30107, 'គណនា \(\lim_{x\to 0^{+}}\log{\left(x \right)}\)។', NULL, '["\\(-\\infty\\)", "\\(1\\)", "\\(0\\)", "\\(+\\infty\\)"]', 0, NULL, 1, 'mcq', 'ពេល \(x\to0^{+}\) តម្លៃ \(\ln x\) ចុះតូចជាអវិជ្ជមានឥតកំណត់ ៖ \(\lim_{x\to0^{+}}\ln x=-\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9c0ac2e6d0.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30108, 'គណនា \(\lim_{x\to 1^{-}}\dfrac{1}{x - 1}\) (ក្រាបដូចក្នុងរូប)។', 'g12sc-9c0ac2e6d0.svg', '["\\(0\\)", "\\(+\\infty\\)", "\\(1\\)", "\\(-\\infty\\)"]', 3, NULL, 1, 'mcq', 'ពេល \(x\to1^{-}\) ភាគបែង \(x-1\to0^{-}\) (អវិជ្ជមានតូច) ភាគយក \(1>0\) ដូច្នេះលីមីត \(=-\infty\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30109, 'គណនា \(\lim_{x\to -\infty}\left(e^{x} + 4\right)\)។', NULL, '["\\(+\\infty\\)", "\\(0\\)", "\\(4\\)", "\\(5\\)"]', 2, NULL, 1, 'mcq', '\(e^x\to0\) កាលណា \(x\to-\infty\) ដូច្នេះលីមីត \(=0+4=4\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30110, 'គណនា \(\lim_{x\to +\infty}\dfrac{2 x + 1}{x - 1}\)។', NULL, '["\\(0\\)", "\\(+\\infty\\)", "\\(2\\)", "\\(1\\)"]', 2, NULL, 1, 'mcq', 'ចែកភាគយក និងភាគបែងនឹង \(x\) ៖ \(\dfrac{2+\frac1x}{1-\frac1x}\to\dfrac21=2\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'easy', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30111, 'គណនា \(\lim_{x\to 4}\dfrac{\sqrt{x} - 2}{x - 4}\)។', NULL, '["\\(\\dfrac{1}{4}\\)", "\\(4\\)", "\\(\\dfrac{1}{2}\\)", "\\(0\\)"]', 0, NULL, 2, 'mcq', 'គុណនឹងអនុញ្ញាតិរួម ៖ \(\dfrac{\sqrt x-2}{x-4}=\dfrac1{\sqrt x+2}\to\dfrac14\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30112, 'គណនា \(\lim_{x\to +\infty}\dfrac{3 x^{2} - x + 5}{2 x^{2} + 7}\)។', NULL, '["\\(\\dfrac{2}{3}\\)", "\\(+\\infty\\)", "\\(3\\)", "\\(\\dfrac{3}{2}\\)"]', 3, NULL, 2, 'mcq', 'ដាក់ \(x^2\) ជាកត្តារួម ៖ \(\dfrac{3-\frac1x+\frac5{x^2}}{2+\frac7{x^2}}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30113, 'គណនា \(\lim_{x\to 0}\dfrac{\sin{\left(5 x \right)}}{\sin{\left(3 x \right)}}\)។', NULL, '["\\(\\dfrac{3}{5}\\)", "\\(1\\)", "\\(15\\)", "\\(\\dfrac{5}{3}\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{\sin5x}{\sin3x}=\dfrac{\sin5x}{5x}\cdot\dfrac{3x}{\sin3x}\cdot\dfrac53\to\dfrac53\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30114, 'គណនា \(\lim_{x\to 0}\dfrac{e^{3 x} - 1}{x}\)។', NULL, '["\\(3\\)", "\\(e^{3}\\)", "\\(1\\)", "\\(0\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{e^{3x}-1}{x}=3\cdot\dfrac{e^{3x}-1}{3x}\to3\cdot1=3\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30115, 'ចំពោះតម្លៃ \(a\) ណា ទើបលីមីត \(\displaystyle\lim_{x\to2}\dfrac{x^2+ax-6}{x-2}\) ជាចំនួនថេរ ?', NULL, '["\\(a=2\\)", "\\(a=3\\)", "\\(a=1\\)", "\\(a=-1\\)"]', 2, NULL, 2, 'mcq', 'ភាគបែង \(\to0\) ដូច្នេះភាគយកត្រូវ \(\to0\) ៖ \(4+2a-6=0\) គឺ \(a=1\) ហើយ \(\dfrac{(x-2)(x+3)}{x-2}\to5\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30116, 'គណនា \(\lim_{x\to +\infty}\sqrt{\dfrac{4 x - 1}{x + 3}}\)។', NULL, '["\\(4\\)", "\\(2\\)", "\\(\\sqrt{2}\\)", "\\(+\\infty\\)"]', 1, NULL, 2, 'mcq', 'លីមីតនៃអនុគមន៍បណ្ដាក់ ៖ \(X=\dfrac{4x-1}{x+3}\to4\) ហើយ \(\sqrt X\to\sqrt4=2\)។', 'លីមីតនៃអនុគមន៍អសនិទាន និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30117, 'គណនា \(\lim_{x\to +\infty}\left(- x + \sqrt{x^{2} + 3 x}\right)\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(+\\infty\\)", "\\(\\dfrac{3}{2}\\)"]', 3, NULL, 2, 'mcq', 'រាង \(\infty-\infty\) ៖ គុណនឹងអនុញ្ញាតិរួម \(\dfrac{3x}{\sqrt{x^2+3x}+x}=\dfrac{3}{\sqrt{1+\frac3x}+1}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30118, 'គណនា \(\lim_{x\to 0}\dfrac{1 - \cos{\left(x \right)}}{x^{2}}\)។', NULL, '["\\(2\\)", "\\(1\\)", "\\(\\dfrac{1}{2}\\)", "\\(0\\)"]', 2, NULL, 2, 'mcq', '\(1-\cos x=2\sin^2\tfrac x2\) ដូច្នេះ \(\dfrac{2\sin^2\frac x2}{x^2}=\dfrac12\left(\dfrac{\sin\frac x2}{\frac x2}\right)^2\to\dfrac12\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30119, 'គណនា \(\lim_{x\to 0}\dfrac{\log{\left(4 x + 1 \right)}}{x}\)។', NULL, '["\\(0\\)", "\\(\\dfrac{1}{4}\\)", "\\(4\\)", "\\(1\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{\ln(1+4x)}{x}=4\cdot\dfrac{\ln(1+4x)}{4x}\to4\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30120, 'គណនា \(\lim_{x\to -\infty}\dfrac{\sqrt{x^{2} + 1}}{x + 2}\)។', NULL, '["\\(0\\)", "\\(-\\infty\\)", "\\(1\\)", "\\(-1\\)"]', 3, NULL, 2, 'mcq', 'ពេល \(x\to-\infty\) គេមាន \(\sqrt{x^2+1}=|x|\sqrt{1+\frac1{x^2}}=-x\sqrt{\cdots}\) ដូច្នេះលីមីត \(=\dfrac{-x}{x}=-1\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30121, 'គណនា \(\lim_{x\to \dfrac{\pi}{2}}\dfrac{\cos{\left(x \right)}}{x - \dfrac{\pi}{2}}\)។', NULL, '["\\(-1\\)", "\\(0\\)", "\\(1\\)", "\\(+\\infty\\)"]', 0, NULL, 2, 'mcq', 'តាង \(\alpha=x-\tfrac\pi2\) ៖ \(\cos(\alpha+\tfrac\pi2)=-\sin\alpha\) ដូច្នេះ \(-\dfrac{\sin\alpha}{\alpha}\to-1\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30122, 'គណនា \(\lim_{x\to +\infty}x e^{- x}\)។', NULL, '["\\(+\\infty\\)", "\\(0\\)", "\\(-\\infty\\)", "\\(1\\)"]', 1, NULL, 2, 'mcq', '\(xe^{-x}=\dfrac{x}{e^x}\to0\) ព្រោះអិចស្ប៉ូណង់ស្យែលធំលឿនជាងស្វ័យគុណ ៖ \(\dfrac{e^x}{x}\to+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30123, 'គណនា \(\lim_{x\to 1}\dfrac{x^{3} - 1}{x^{2} - 1}\)។', NULL, '["\\(0\\)", "\\(3\\)", "\\(\\dfrac{3}{2}\\)", "\\(1\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{(x-1)(x^2+x+1)}{(x-1)(x+1)}=\dfrac{x^2+x+1}{x+1}\to\dfrac32\)។', 'លីមីតរាងមិនកំណត់', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30124, 'គណនា \(\lim_{x\to 0^{+}}x \log{\left(x \right)}\)។', NULL, '["\\(1\\)", "\\(0\\)", "\\(-1\\)", "\\(-\\infty\\)"]', 1, NULL, 2, 'mcq', 'តាង \(x=\tfrac1X\) ៖ \(x\ln x=-\dfrac{\ln X}{X}\to0\) កាលណា \(X\to+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30125, 'គណនា \(\lim_{x\to 0}\dfrac{e^{2 x} - e^{- x}}{x}\)។', NULL, '["\\(1\\)", "\\(3\\)", "\\(2\\)", "\\(0\\)"]', 1, NULL, 3, 'mcq', '\(\dfrac{e^{2x}-1}{x}+\dfrac{1-e^{-x}}{x}\to2+1=3\) ព្រោះ \(\dfrac{1-e^{-x}}{x}=\dfrac{e^{-x}-1}{-x}\to1\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30126, 'គណនា \(\lim_{x\to +\infty}\left(- \sqrt{x^{2} - 2 x} + \sqrt{x^{2} + 4 x + 1}\right)\)។', NULL, '["\\(6\\)", "\\(1\\)", "\\(\\dfrac{3}{2}\\)", "\\(3\\)"]', 3, NULL, 3, 'mcq', 'ផលដក ៖ \(\dfrac{6x+1}{\sqrt{x^2+4x+1}+\sqrt{x^2-2x}}=\dfrac{6+\frac1x}{\sqrt{1+\frac4x+\cdots}+\sqrt{1-\frac2x}}\to\dfrac62=3\)។', 'លីមីតរាងមិនកំណត់', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30127, 'គណនា \(\lim_{x\to 0}\dfrac{- \sqrt{1 - x} + \sqrt{x + 1}}{\sin{\left(3 x \right)}}\)។', NULL, '["\\(\\dfrac{1}{3}\\)", "\\(3\\)", "\\(\\dfrac{2}{3}\\)", "\\(\\dfrac{1}{6}\\)"]', 0, NULL, 3, 'mcq', 'គុណអនុញ្ញាតិរួម ៖ \(\dfrac{2x}{(\sqrt{1+x}+\sqrt{1-x})\sin3x}=\dfrac{2}{3\cdot\frac{\sin3x}{3x}(\sqrt{1+x}+\sqrt{1-x})}\to\dfrac{2}{3\cdot2}=\dfrac13\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30128, 'ទំនាក់ទំនងមួយណាខាងក្រោមត្រឹមត្រូវ ?', NULL, '["\\(\\displaystyle\\lim_{x\\to0}\\dfrac{\\sin2x}{x}=1\\)", "\\(\\displaystyle\\lim_{x\\to0}\\dfrac{e^x-1}{x}=0\\)", "\\(\\displaystyle\\lim_{x\\to0^-}\\dfrac{x}{|x|}=-1\\)", "\\(\\displaystyle\\lim_{x\\to+\\infty}\\dfrac{\\ln x}{x}=+\\infty\\)"]', 2, NULL, 3, 'mcq', 'ចំពោះ \(x<0\) ៖ \(|x|=-x\) ដូច្នេះ \(\dfrac x{|x|}=-1\)។ ឯខ្សែផ្សេងទៀតខុស ៖ \(\dfrac{\sin2x}x\to2\), \(\dfrac{\ln x}x\to0\), \(\dfrac{e^x-1}x\to1\)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30129, 'គណនា \(\lim_{x\to +\infty}\left(- x^{3} + e^{x}\right)\)។', NULL, '["\\(0\\)", "\\(1\\)", "\\(+\\infty\\)", "\\(-\\infty\\)"]', 2, NULL, 3, 'mcq', '\(e^x-x^3=x^3\left(\dfrac{e^x}{x^3}-1\right)\) ដោយ \(\dfrac{e^x}{x^3}\to+\infty\) ដូច្នេះលីមីត \(=+\infty\)។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30130, 'គណនា \(\lim_{x\to 1}\dfrac{x^{10} - 1}{x^{4} - 1}\)។', NULL, '["\\(\\dfrac{2}{5}\\)", "\\(\\dfrac{5}{2}\\)", "\\(6\\)", "\\(1\\)"]', 1, NULL, 3, 'mcq', 'ប្រើ \(\displaystyle\lim_{x\to1}\dfrac{x^m-1}{x^n-1}=\dfrac mn\) ដែល \(m=10,\ n=4\) ៖ \(\dfrac{10}4=\dfrac52\)។', 'លីមីតរាងមិនកំណត់', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30131, 'គណនា \(\lim_{x\to 0}\dfrac{1 - \cos{\left(4 x \right)}}{x \sin{\left(x \right)}}\)។', NULL, '["\\(8\\)", "\\(4\\)", "\\(2\\)", "\\(16\\)"]', 0, NULL, 3, 'mcq', '\(1-\cos4x=2\sin^22x\) ៖ \(\dfrac{2\sin^22x}{x\sin x}=2\left(\dfrac{\sin2x}{2x}\right)^2\cdot\dfrac{4x^2}{x\sin x}\to2\cdot4=8\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'hard', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-1cc594c372.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30132, 'កាហ្វេក្តៅមួយកែវដាក់ក្នុងបន្ទប់ ។ សីតុណ្ហភាព (°C) ក្រោយ \(t\) នាទី គឺ \(T(t)=25+60e^{-t/10}\) ដូចក្នុងរូប ។ តើសីតុណ្ហភាពកាហ្វេខិតទៅរកតម្លៃប៉ុន្មាន (គិតជា °C) កាលណា \(t\) ធំឥតកំណត់ ?', 'g12sc-1cc594c372.svg', '["\\(60\\)", "\\(85\\)", "\\(0\\)", "\\(25\\)"]', 3, NULL, 3, 'mcq', '\(e^{-t/10}\to0\) ដូច្នេះ \(T\to25+0=25\) °C (សីតុណ្ហភាពបន្ទប់) ដែលក្រាបមាន \(y=25\) ជាអាស៊ីមតូតដេក។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-c9420b9810.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30133, 'តារាងតម្លៃតាក់ស៊ី \(F(x)\) (ដុល្លារ) តាមចម្ងាយ \(x\) (គីឡូម៉ែត្រ) ត្រូវបានបង្ហាញដោយក្រាបក្នុងរូប ។ គណនា \(\displaystyle\lim_{x\to6^{+}}F(x)-\lim_{x\to6^{-}}F(x)\) ។', 'g12sc-c9420b9810.svg', '["\\(0\\)", "\\(3\\)", "\\(11\\)", "\\(8\\)"]', 1, NULL, 3, 'mcq', 'ពីក្រាប ៖ \(\lim_{x\to6^-}F(x)=8\) (ជណ្ដើរមុន) និង \(\lim_{x\to6^+}F(x)=11\) (ជណ្ដើរបន្ទាប់) ដូច្នេះផលដក \(11-8=3\) ហើយលីមីតនៅ \(x=6\) មិនមាន (លោត \(3\) ដុល្លារ)។', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'pisa', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-4aafb1e6fa.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30134, 'ក្នុងរង្វង់កាំ \(1\) ធ្នូ \(AB\) ប្រវែង \(s=\theta\) ហើយអង្កត់ធ្នូ \(AB=c=2\sin\dfrac\theta2\) ដូចក្នុងរូប ។ តើសមាមាត្រ \(\dfrac cs\) ខិតទៅរកអ្វី កាលណា \(\theta\to0\) ?', 'g12sc-4aafb1e6fa.svg', '["\\(\\dfrac12\\)", "\\(2\\)", "\\(0\\)", "\\(1\\)"]', 3, NULL, 3, 'mcq', '\(\dfrac cs=\dfrac{2\sin\frac\theta2}{\theta}=\dfrac{\sin\frac\theta2}{\frac\theta2}\to1\) ដូច្នេះ \(c\approx s\) កាលណាមុំតូច។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'pisa', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-0a7b64e123.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30135, 'ក្បួនដោះស្រាយមួយមានប្រសិទ្ធភាព \(E(n)=\dfrac{\ln n}{n}\) ដែល \(n\) ជាចំនួនទិន្នន័យ ដូចក្នុងរូប ។ តើប្រសិទ្ធភាពខិតទៅរកអ្វី កាលណា \(n\to+\infty\) ?', 'g12sc-0a7b64e123.svg', '["\\(0\\)", "\\(1\\)", "\\(+\\infty\\)", "\\(\\dfrac1e\\)"]', 0, NULL, 3, 'mcq', '\(\displaystyle\lim_{n\to+\infty}\dfrac{\ln n}{n}=0\) ព្រោះ \(\ln n\) កើនយឺតជាង \(n\)។ តម្លៃធំបំផុត \(\dfrac1e\approx0{,}37\) ត្រង់ \(n=e\) មិនមែនជាលីមីតទេ។', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-9e42055127.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30136, 'ពហុកោណនិយ័ត \(n\) ជ្រុងចារឹកក្នុងរង្វង់កាំ \(1\) (រូបបង្ហាញ \(n=6\)) មានបរិមាត្រ \(P_n=2n\sin\dfrac\pi n\) ។ តើ \(P_n\) ខិតទៅរកអ្វី កាលណា \(n\to+\infty\) ?', 'g12sc-9e42055127.svg', '["\\(\\pi\\)", "\\(2\\)", "\\(2\\pi\\)", "\\(4\\pi\\)"]', 2, NULL, 3, 'mcq', '\(P_n=2\pi\cdot\dfrac{\sin\frac\pi n}{\frac\pi n}\to2\pi\cdot1=2\pi\) ជាបរិមាត្ររង្វង់កាំ \(1\)។', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'pisa', 1, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30137, 'គណនាលីមីត \(\displaystyle\lim_{x\to-1}\dfrac{x^2-1}{x^2+3x+2}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ជំនួស \(x=-1\) ៖ ភាគយក \(=0\) និងភាគបែង \(=0\) ដូច្នេះមានរាងមិនកំណត់ \(\tfrac00\) (1 ពិន្ទុ)
ដាក់ជាកត្តា ៖ \(x^2-1=(x-1)(x+1)\) (1 ពិន្ទុ)
ភាគបែង ៖ \(x^2+3x+2=(x+1)(x+2)\) (1 ពិន្ទុ)
សម្រួលកត្តារួម \((x+1)\) (ព្រោះ \(x\ne-1\)) ៖ \(\dfrac{x-1}{x+2}\) (1 ពិន្ទុ)
ជំនួស \(x=-1\) ៖ \(\dfrac{-1-1}{-1+2}=-2\) ដូច្នេះលីមីត \(=-2\)។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'easy', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30138, 'គណនា \(\displaystyle\lim_{x\to+\infty}\left(\sqrt{x^2+x+1}-\sqrt{x^2-x}\right)\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'រាងមិនកំណត់ \(+\infty-\infty\) ដូច្នេះគុណ និងចែកនឹងអនុញ្ញាតិរួម \(\sqrt{x^2+x+1}+\sqrt{x^2-x}\) (1 ពិន្ទុ)
ភាគយក ៖ \((x^2+x+1)-(x^2-x)=2x+1\) (1 ពិន្ទុ)
ដាក់ \(x\) ជាកត្តារួម ៖ \(\dfrac{x\left(2+\frac1x\right)}{x\left(\sqrt{1+\frac1x+\frac1{x^2}}+\sqrt{1-\frac1x}\right)}\) (1 ពិន្ទុ)
សម្រួល \(x\) (ព្រោះ \(x>0\)) ទុកប្រភាគ \(\dfrac{2+\frac1x}{\sqrt{1+\frac1x+\frac1{x^2}}+\sqrt{1-\frac1x}}\) (1 ពិន្ទុ)
ឱ្យ \(x\to+\infty\) ៖ \(\dfrac{2+0}{\sqrt1+\sqrt1}=1\) ដូច្នេះលីមីត \(=1\)។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'medium', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30139, 'គណនា \(\displaystyle\lim_{x\to0}\dfrac{1-\cos3x}{x^2}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'រាងមិនកំណត់ \(\tfrac00\) ព្រោះ \(1-\cos0=0\) (1 ពិន្ទុ)
ប្រើ \(1-\cos\alpha=2\sin^2\tfrac\alpha2\) ៖ \(1-\cos3x=2\sin^2\tfrac{3x}2\) (1 ពិន្ទុ)
សរសេរ \(\dfrac{2\sin^2\frac{3x}2}{x^2}=2\cdot\dfrac94\left(\dfrac{\sin\frac{3x}2}{\frac{3x}2}\right)^2\) ព្រោះ \(\left(\tfrac{3x}2\right)^2=\tfrac94x^2\) (1 ពិន្ទុ)
ប្រើ \(\displaystyle\lim_{u\to0}\dfrac{\sin u}u=1\) ជាមួយ \(u=\tfrac{3x}2\to0\) (1 ពិន្ទុ)
លីមីត \(=2\cdot\dfrac94\cdot1^2=\dfrac92\)។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍ត្រីកោណមាត្រ', 'medium', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30140, 'កំណត់ចំនួនថេរ \(a\) និង \(b\) ដើម្បីឱ្យ \(\displaystyle\lim_{x\to1}\dfrac{x^2+ax+b}{x-1}=3\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដោយភាគបែង \(x-1\to0\) ហើយលីមីតជាចំនួនកំណត់ ដូច្នេះភាគយកត្រូវ \(\to0\) ត្រង់ \(x=1\) (1 ពិន្ទុ)
លក្ខខណ្ឌ ៖ \(1+a+b=0\) គឺ \(b=-1-a\) (1 ពិន្ទុ)
ដាក់ជាកត្តា ៖ \(x^2+ax-1-a=(x-1)(x+1+a)\) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{x^2+ax+b}{x-1}=x+1+a\) ដូច្នេះលីមីត \(=2+a\) (1 ពិន្ទុ)
ឱ្យ \(2+a=3\) បាន \(a=1\) ហើយ \(b=-2\) ។ ផ្ទៀងផ្ទាត់ \(\dfrac{(x-1)(x+2)}{x-1}\to3\)។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'medium', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30141, 'គណនា \(\displaystyle\lim_{x\to0}\dfrac{e^{5x}-e^{2x}}{\ln(1+3x)}\) ។', NULL, '[]', 0, NULL, 5, 'writing', 'ទាំងភាគយក និងភាគបែង \(\to0\) ដូច្នេះរាង \(\tfrac00\) ។ ចែកភាគយក និងភាគបែងនឹង \(x\) (1 ពិន្ទុ)
ភាគយក ៖ \(\dfrac{e^{5x}-e^{2x}}x=\dfrac{e^{5x}-1}x-\dfrac{e^{2x}-1}x\) (1 ពិន្ទុ)
ប្រើ \(\dfrac{e^{ax}-1}{ax}\to1\) ៖ ភាគយក \(\to5-2=3\) (1 ពិន្ទុ)
ភាគបែង ៖ \(\dfrac{\ln(1+3x)}x=3\cdot\dfrac{\ln(1+3x)}{3x}\to3\) (1 ពិន្ទុ)
ដូច្នេះលីមីត \(=\dfrac33=1\)។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'medium', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
