INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30142, 'ក្រាបក្នុងរូបបង្ហាញអនុគមន៍ \(f(x)=\dfrac{2x+\sin x}{x+1}\) ដែលស្ថិតចន្លោះ \(g(x)=\dfrac{2x-1}{x+1}\) និង \(h(x)=\dfrac{2x+1}{x+1}\) ចំពោះ \(x\ge0\)។ ក. បង្ហាញថា \(g(x)\le f(x)\le h(x)\) ។ ខ. ដោយប្រើទ្រឹស្ដីបទកៀប រកលីមីតនៃ \(f(x)\) កាលណា \(x\to+\infty\)។', 'g12sc-d70bf149ab.svg', '[]', 0, NULL, 5, 'writing', 'ដោយ \(-1\le\sin x\le1\) ដូច្នេះ \(2x-1\le2x+\sin x\le2x+1\) (1 ពិន្ទុ)
ចែកនឹង \(x+1>0\) (មិនប្ដូរទិស) ៖ \(g(x)\le f(x)\le h(x)\) ចំពោះ \(x\ge0\) (1 ពិន្ទុ)
លីមី \(g\) ៖ \(\dfrac{2x-1}{x+1}=\dfrac{2-\frac1x}{1+\frac1x}\to2\) (1 ពិន្ទុ)
លីមី \(h\) ៖ \(\dfrac{2x+1}{x+1}=\dfrac{2+\frac1x}{1+\frac1x}\to2\) (1 ពិន្ទុ)
ទ្រឹស្ដីបទកៀប ៖ \(g\to2\) និង \(h\to2\) ដូច្នេះ \(\displaystyle\lim_{x\to+\infty}f(x)=2\) (ក្រាប \(f\) ត្រូវចងក្នុងក្រាប \(g\) និង \(h\))។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30143, 'ក. បង្ហាញថា \(\displaystyle\lim_{x\to+\infty}x\left(e^{1/x}-1\right)=1\) ដោយប្ដូរអថេរ ។ ខ. ទាញរក \(\displaystyle\lim_{x\to+\infty}x\left(e^{3/x}-1\right)\) ។ គ. ពន្យល់ថាហេតុអ្វីលីមីតនេះមិនអាចរកដោយជំនួស \(x=+\infty\) ត្រង់ៗ បាន។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(u=\dfrac1x\) ដូច្នេះ \(x\to+\infty\) គឺ \(u\to0^{+}\) (1 ពិន្ទុ)
សរសេរ \(x\left(e^{1/x}-1\right)=\dfrac{e^u-1}{u}\) (1 ពិន្ទុ)
ប្រើលីមីតគោល \(\dfrac{e^u-1}u\to1\) ដូច្នេះ ក. \(=1\) (1 ពិន្ទុ)
ខ. តាង \(v=\dfrac3x\to0\) ៖ \(x\left(e^{3/x}-1\right)=3\cdot\dfrac{e^v-1}{v}\to3\) (1 ពិន្ទុ)
គ. ជំនួសត្រង់ៗ បានរាង \(\infty\cdot0\) ជារាងមិនកំណត់ (ស្វ័យគុណ \(x\to\infty\) ប៉ុន្តែ \(e^{1/x}-1\to0\)) ដូច្នេះត្រូវប្ដូរអថេរដើម្បីឱ្យទៅជាលីមីតគោល។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'hard', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-751a0f9010.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30144, 'ដោយប្រើនិយមន័យ \(\varepsilon\)–\(\delta\) បង្ហាញថា \(\displaystyle\lim_{x\to3}(4x-5)=7\) (ក្រាបក្នុងរូបបង្ហាញចន្លោះ \(3\pm\delta\) និង \(7\pm\varepsilon\)) រួចរក \(\delta\) ធំបំផុតដែលបានពី \(\varepsilon=0{,}02\)។', 'g12sc-751a0f9010.svg', '[]', 0, NULL, 5, 'writing', 'ត្រូវការ ៖ ចំពោះគ្រប់ \(\varepsilon>0\) មាន \(\delta>0\) ដែល \(0<|x-3|<\delta\) នាំឱ្យ \(|f(x)-7|<\varepsilon\) (1 ពិន្ទុ)
គណនា ៖ \(|f(x)-7|=|4x-5-7|=|4x-12|=4|x-3|\) (1 ពិន្ទុ)
ដើម្បីឱ្យ \(4|x-3|<\varepsilon\) ត្រូវ \(|x-3|<\dfrac\varepsilon4\) (1 ពិន្ទុ)
យក \(\delta=\dfrac\varepsilon4\) ៖ \(0<|x-3|<\delta\) នាំឱ្យ \(|f(x)-7|=4|x-3|<4\delta=\varepsilon\) ដូច្នេះលីមីត \(=7\) (1 ពិន្ទុ)
ចំពោះ \(\varepsilon=0{,}02\) ៖ \(\delta=\dfrac{0{,}02}4=0{,}005\)។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30145, 'កំណត់អនុគមន៍ដឺក្រេទី ២ \(f(x)=px^2+qx+r\) (\(p\ne0\)) ដែលបំពេញលក្ខខណ្ឌទាំងពីរ ៖ \(\displaystyle\lim_{x\to+\infty}\dfrac{f(x)}{x^2-1}=2\) និង \(\displaystyle\lim_{x\to1}\dfrac{f(x)}{x^2-1}=-1\)។', NULL, '[]', 0, NULL, 5, 'writing', 'កាលណា \(x\to+\infty\) ៖ \(\dfrac{px^2+qx+r}{x^2-1}\to p\) ដូច្នេះ \(p=2\) (1 ពិន្ទុ)
ភាគបែង \(x^2-1\to0\) កាលណា \(x\to1\) ដូច្នេះត្រូវ \(f(1)=0\) គឺ \(2+q+r=0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(x)=(x-1)(2x+c)\) ជាមួយចំនួនថេរ \(c\) (ព្រោះ \(f(1)=0\) និង \(p=2\)) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{f(x)}{x^2-1}=\dfrac{2x+c}{x+1}\) ហើយកាលណា \(x\to1\) បាន \(\dfrac{2+c}2=-1\) ដូច្នេះ \(c=-4\) (1 ពិន្ទុ)
ចម្លើយ ៖ \(f(x)=(x-1)(2x-4)=2x^2-6x+4\) ផ្ទៀងផ្ទាត់ \(\dfrac{2(x-2)}{x+1}\) \(\to2\) (កាលណា \(x\to+\infty\)) និង \(\to-1\) (កាលណា \(x\to1\))។ (1 ពិន្ទុ)', 'លីមីតតាមនិយមន័យ និងប្រមាណវិធី', 'hard', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-77b5f243ac.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30146, 'កំហាប់ថ្នាំក្នុងឈាម (mg/L) បន្ទាប់ពីចាក់ \(t\) ម៉ោង ត្រូវបានគណនាដោយ \(C(t)=\dfrac{20t}{t+4}\) ដូចក្នុងរូប ។ ក. គណនា \(C(4)\)។ ខ. រកកំហាប់ដែលខិតជិតក្នុងរយៈពេលវែង \(\displaystyle\lim_{t\to+\infty}C(t)\)។ គ. តើក្រោយប៉ុន្មានម៉ោងទើបកំហាប់ដល់ \(90\%\) នៃតម្លៃលីមីតនេះ ?', 'g12sc-77b5f243ac.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(C(4)=\dfrac{20\cdot4}{4+4}=10\) mg/L (1 ពិន្ទុ)
ខ. ចែកភាគយក និងភាគបែងនឹង \(t\) ៖ \(C(t)=\dfrac{20}{1+\frac4t}\) (1 ពិន្ទុ)
ឱ្យ \(t\to+\infty\) ៖ \(\dfrac4t\to0\) ដូច្នេះលីមីត \(=20\) mg/L (អាស៊ីមតូតដេក \(y=20\)) (1 ពិន្ទុ)
គ. \(90\%\) នៃ \(20\) គឺ \(18\) ៖ \(\dfrac{20t}{t+4}=18\) គឺ \(20t=18t+72\) (1 ពិន្ទុ)
ដូច្នេះ \(2t=72\) បាន \(t=36\) ម៉ោង។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'pisa', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-5507debb52.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30147, 'កុងដង់សាទ័រមួយសាកថាមពល ដោយបន្ទុកក្នុងវា (µC) ក្រោយ \(t\) វិនាទី គឺ \(Q(t)=50\left(1-e^{-t/2}\right)\) ដូចក្នុងរូប ។ ក. រកបន្ទុកដែលខិតជិតពេល \(t\to+\infty\)។ ខ. រកពេលវេលាដែល \(Q=47{,}5\) (គឺ \(95\%\) នៃតម្លៃអតិបរមា) ។ គ. គណនាអត្រាដើម \(\displaystyle\lim_{t\to0}\dfrac{Q(t)}t\)។', 'g12sc-5507debb52.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(e^{-t/2}\to0\) ដូច្នេះ \(Q\to50(1-0)=50\) µC (1 ពិន្ទុ)
ខ. \(50\left(1-e^{-t/2}\right)=47{,}5\) គឺ \(e^{-t/2}=0{,}05\) (1 ពិន្ទុ)
យកលោការីតនេពែ ៖ \(-\dfrac t2=\ln0{,}05=-\ln20\) ដូច្នេះ \(t=2\ln20\approx5{,}99\) s (1 ពិន្ទុ)
គ. \(\dfrac{Q(t)}t=50\cdot\dfrac{1-e^{-t/2}}{t}=25\cdot\dfrac{e^{-t/2}-1}{-t/2}\) (1 ពិន្ទុ)
ប្រើ \(\dfrac{e^u-1}u\to1\) ជាមួយ \(u=-\tfrac t2\to0\) ៖ អត្រាដើម \(=25\) µC/s។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-a69b5ac61e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30148, 'រោងចក្រមួយមានចំណាយថេរ \(2\,000\) ដុល្លារ និងចំណាយលើអង្គមួយ \(15\) ដុល្លារ ។ ចំណាយមធ្យមក្នុងអង្គមួយនៅពេលផលិត \(x\) អង្គ គឺ \(C(x)=\dfrac{2\,000+15x}{x}\) ដូចក្នុងរូប ។ ក. គណនា \(C(100)\)។ ខ. រកលីមីត \(\displaystyle\lim_{x\to+\infty}C(x)\) ហើយបកស្រាយ។ គ. រកចំនួនអង្គតិចបំផុតដើម្បីឱ្យ \(C(x)<16\)។', 'g12sc-a69b5ac61e.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(C(100)=\dfrac{2\,000+1\,500}{100}=35\) ដុល្លារ/អង្គ (1 ពិន្ទុ)
ខ. សរសេរ \(C(x)=\dfrac{2\,000}x+15\) (1 ពិន្ទុ)
ឱ្យ \(x\to+\infty\) ៖ \(\dfrac{2\,000}x\to0\) ដូច្នេះ \(C\to15\) ដុល្លារ/អង្គ (ចំណាយផ្លាស់ប្ដូរ ដោយចំណាយថេរចែកទៅអង្គច្រើនឥតកំណត់) (1 ពិន្ទុ)
គ. \(\dfrac{2\,000}x+15<16\) គឺ \(\dfrac{2\,000}x<1\) (1 ពិន្ទុ)
ដោយ \(x>0\) ៖ \(x>2\,000\) ដូច្នេះតិចបំផុតគឺ \(2\,001\) អង្គ។ (1 ពិន្ទុ)', 'លីមីតរាងមិនកំណត់', 'pisa', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-f354828a34.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30149, 'សញ្ញាសំឡេងមួយអន់ថយតាមពេលវេលា ដោយវ៉ុលរបស់វា (V) គឺ \(V(t)=12e^{-0{,}2t}\) (t គិតជាវិនាទី) ដូចក្នុងរូប ។ ក. រក \(\displaystyle\lim_{t\to+\infty}V(t)\)។ ខ. តើពេលណាវ៉ុលនៅសល់ពាក់កណ្ដាលតម្លៃដើម ? គ. បង្ហាញថា \(\displaystyle\lim_{t\to+\infty}t^3V(t)=0\) ហើយបកស្រាយ។', 'g12sc-f354828a34.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(-0{,}2t\to-\infty\) ដូច្នេះ \(e^{-0{,}2t}\to0\) ហើយ \(V\to0\) V (1 ពិន្ទុ)
ខ. \(12e^{-0{,}2t}=6\) គឺ \(e^{-0{,}2t}=\tfrac12\) (1 ពិន្ទុ)
យកលោការីត ៖ \(-0{,}2t=-\ln2\) ដូច្នេះ \(t=5\ln2\approx3{,}47\) s (1 ពិន្ទុ)
គ. \(t^3V(t)=12t^3e^{-0{,}2t}\) តាង \(u=0{,}2t\) ៖ \(12\cdot125\,u^3e^{-u}\) (1 ពិន្ទុ)
ដោយ \(\dfrac{u^3}{e^u}\to0\) កាលណា \(u\to+\infty\) ដូច្នេះលីមី \(=0\) ៖ អិចស្ប៉ូណង់ស្យែលអន់ថយលឿនជាងស្វ័យគុណនៃ \(t\) កើន។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-ac3d77bdc3.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30150, 'ចំនួនត្រីក្នុងបឹងមួយ ក្រោយ \(t\) ឆ្នាំ ត្រូវបានគណនាដោយ \(P(t)=\dfrac{5\,000}{1+49e^{-0{,}4t}}\) ដូចក្នុងរូប ។ ក. រក \(P(0)\)។ ខ. រកលីមីត \(\displaystyle\lim_{t\to+\infty}P(t)\) (សមត្ថភាពអតិបរមា) ។ គ. តើក្រោយប៉ុន្មានឆ្នាំ ចំនួនត្រីដល់ពាក់កណ្ដាលសមត្ថភាព ? ឃ. វាយតម្លៃថាតើបឹងអាចមានត្រី \(6\,000\) ក្បាលដែរឬទេ ?', 'g12sc-ac3d77bdc3.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(P(0)=\dfrac{5\,000}{1+49}=100\) ក្បាល (1 ពិន្ទុ)
ខ. \(e^{-0{,}4t}\to0\) ដូច្នេះ \(P\to\dfrac{5\,000}{1+0}=5\,000\) ក្បាល (1 ពិន្ទុ)
គ. \(P=2\,500\) ៖ \(1+49e^{-0{,}4t}=2\) គឺ \(e^{-0{,}4t}=\dfrac1{49}\) (1 ពិន្ទុ)
ដូច្នេះ \(t=\dfrac{\ln49}{0{,}4}\approx9{,}73\) ឆ្នាំ (1 ពិន្ទុ)
ឃ. \(1+49e^{-0{,}4t}>1\) ដូច្នេះ \(P(t)<5\,000\) គ្រប់ \(t\) ហើយ \(P\to5\,000\) ដូច្នេះមិនអាចមាន \(6\,000\) ក្បាលបានទេ (អាស៊ីមតូត \(y=5\,000\))។ (1 ពិន្ទុ)', 'លីមីតនៃអនុគមន៍អិចស្ប៉ូណង់ស្យែល និងលោការីត', 'pisa', 0, '12SS', 'លីមីតនៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30201, 'អនុគមន៍ \(y=f(x)\) ជាប់ត្រង់ចំណុច \(x=c\) កាលណា ៖', NULL, '["\\(\\displaystyle\\lim_{x\\to c}f(x)=f(c)\\)", "\\(f(c)=0\\)", "\\(f''(c)\\) មាន", "\\(\\displaystyle\\lim_{x\\to c}f(x)=+\\infty\\)"]', 0, NULL, 1, 'mcq', 'និយមន័យ ៖ \(f\) កំណត់ត្រង់ \(c\) មានលីមីតកាលណា \(x\to c\) ហើយ \(\displaystyle\lim_{x\to c}f(x)=f(c)\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30202, 'អនុគមន៍ \(f(x)=3 x^{2} + x - 7\) ជាប់ចំពោះតម្លៃ \(x\) ណាខ្លះ ?', NULL, '["\\(x\\ne1\\)", "\\(x\\ne0\\)", "\\(x\\in\\mathbb{R}\\)", "\\(x>0\\)"]', 2, NULL, 1, 'mcq', '\(f\) ជាអនុគមន៍ពហុធា ដូច្នេះជាប់គ្រប់ចំនួនពិត។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30203, 'បើអនុគមន៍ \(f\) ជាប់លើ \([a,b]\) ហើយ \(f(a)<0<f(b)\) នោះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាល ៖', NULL, '["មាន \\(c\\in(a,b)\\) ដែល \\(f(c)=0\\)", "មាន \\(c\\) ដែល \\(f''(c)=0\\)", "\\(f(x)>0\\) គ្រប់ \\(x\\in[a,b]\\)", "\\(f\\) កើនដាច់ខាតលើ \\([a,b]\\)"]', 0, NULL, 1, 'mcq', 'ដោយ \(0\) នៅចន្លោះ \(f(a)\) និង \(f(b)\) ហើយ \(f\) ជាប់ ដូច្នេះមាន \(c\in(a,b)\) ដែល \(f(c)=0\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30204, 'ដើម្បីបន្ថាយ \(f(x)=\dfrac{x^2-9}{x-3}\) តាមភាពជាប់ត្រង់ \(x=3\) ត្រូវកំណត់ \(g(3)\) ស្មើនឹងលីមីត \(\lim_{x\to 3}\dfrac{x^{2} - 9}{x - 3}\)។', NULL, '["\\(0\\)", "\\(9\\)", "\\(3\\)", "\\(6\\)"]', 3, NULL, 1, 'mcq', 'សម្រួល \(\dfrac{(x-3)(x+3)}{x-3}=x+3\to6\) ដូច្នេះត្រូវកំណត់ \(g(3)=6\) ដើម្បីឱ្យបន្ថាយជាប់។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30205, 'ចន្លោះបិទធំបំផុតដែលអនុគមន៍ \(f(x)=\sqrt{4-x^2}\) ជាប់ គឺ ៖', NULL, '["\\(\\mathbb{R}\\)", "\\([-2,2]\\)", "\\((-2,2)\\)", "\\([0,2]\\)"]', 1, NULL, 1, 'mcq', 'ដែនកំណត់ \(4-x^2\ge0\) គឺ \(-2\le x\le2\) ហើយ \(f\) ជាប់ត្រង់ចុងទាំងពីរ (ខាងស្ដាំនៃ \(-2\) ខាងឆ្វេងនៃ \(2\))។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30206, 'គេមាន \(f(x)=|x|\)។ តើ \(f\) ជាប់ត្រង់ \(x=0\) ឬទេ ?', NULL, '["ដាច់ ព្រោះ \\(\\lim_{x\\to0}f(x)\\ne f(0)\\)", "ជាប់ ព្រោះ \\(\\lim_{x\\to0}|x|=0=f(0)\\)", "ដាច់ ព្រោះ \\(f(0)\\) មិនកំណត់", "ដាច់ ព្រោះលីមីតមិនមាន"]', 1, NULL, 1, 'mcq', '\(\lim_{x\to0^+}x=0\) និង \(\lim_{x\to0^-}(-x)=0\) ដូច្នេះ \(\lim_{x\to0}|x|=0=f(0)\) គឺ ជាប់។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30207, 'អនុគមន៍ \(f(x)=\dfrac{x + 1}{x - 4}\) ដាច់ត្រង់តម្លៃ \(x\) ណា ?', NULL, '["\\(x=-1\\)", "\\(x=0\\)", "\\(x=4\\)", "\\(x=-4\\)"]', 2, NULL, 1, 'mcq', 'អនុគមន៍សនិទានដាច់ត្រង់ចំណុចដែលភាគបែងសូន្យ ៖ \(x-4=0\) គឺ \(x=4\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30208, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} x + 3 & \text{បើ } x<1 \\ a x + 1 & \text{បើ } x\ge1 \end{cases}\) ជាប់ត្រង់ \(x=1\)។', NULL, '["\\(a=4\\)", "\\(a=3\\)", "\\(a=2\\)", "\\(a=1\\)"]', 1, NULL, 1, 'mcq', 'ខាងឆ្វេង ៖ \(1+3=4\) ; ខាងស្ដាំនិង \(f(1)\) ៖ \(a+1\) ។ ត្រូវ \(a+1=4\) គឺ \(a=3\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30209, 'អនុគមន៍ \(y=\tan x\) ដាច់ត្រង់តម្លៃមួយណាខាងក្រោម ?', NULL, '["\\(x=\\dfrac\\pi2\\)", "\\(x=\\dfrac\\pi4\\)", "\\(x=0\\)", "\\(x=\\pi\\)"]', 0, NULL, 1, 'mcq', '\(\tan x=\dfrac{\sin x}{\cos x}\) ហើយ \(\cos\dfrac\pi2=0\) ដូច្នេះមិនកំណត់ត្រង់ \(\dfrac\pi2\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30210, 'បើអនុគមន៍ \(f\) និង \(g\) ជាប់ត្រង់ \(x=c\) នោះ \(\dfrac{f(x)}{g(x)}\) ជាប់ត្រង់ \(x=c\) លុះត្រាតែ ៖', NULL, '["\\(f(c)=g(c)\\)", "\\(f(c)\\ne0\\)", "\\(g(c)=0\\)", "\\(g(c)\\ne0\\)"]', 3, NULL, 1, 'mcq', 'លក្ខណៈនៃភាពជាប់ ៖ ផលចែកជាប់ដរាបណាភាគបែង \(g(c)\ne0\)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'easy', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Remember');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30211, 'អនុគមន៍ \(f(x)=\dfrac{x^2-4}{x^2-5x+6}\) ដាច់ត្រង់តម្លៃ \(x\) ណាខ្លះ ?', NULL, '["\\(x=-2\\) និង \\(x=2\\)", "\\(x=2\\) តែមួយ", "\\(x=3\\) តែមួយ", "\\(x=2\\) និង \\(x=3\\)"]', 3, NULL, 2, 'mcq', '\(x^2-5x+6=(x-2)(x-3)\) ដូច្នេះមិនកំណត់ត្រង់ \(2\) និង \(3\)។ (ត្រង់ \(2\) ដាច់ព្រោះមិនកំណត់ទោះមានលីមីត)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30212, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} x^{2} - 1 & \text{បើ } x<0 \\ a - x & \text{បើ } x\ge0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(a=1\\)", "\\(a=-2\\)", "\\(a=0\\)", "\\(a=-1\\)"]', 3, NULL, 2, 'mcq', 'ខាងឆ្វេង \(\to-1\) ; \(f(0)=a-0=a\) ។ ត្រូវ \(a=-1\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30213, 'គេមាន \(f(x)=\dfrac{x^2+x-6}{x-2}\) ដែល \(x\ne2\)។ អនុគមន៍បន្ថាយតាមភាពជាប់ត្រង់ \(x=2\) មានតម្លៃ \(g(2)\) ស្មើនឹងលីមីត \(\lim_{x\to 2}\dfrac{x^{2} + x - 6}{x - 2}\)។', NULL, '["\\(4\\)", "\\(6\\)", "\\(5\\)", "\\(0\\)"]', 2, NULL, 2, 'mcq', '\(\dfrac{(x+3)(x-2)}{x-2}=x+3\to5\) ដូច្នេះ \(g(2)=5\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30214, 'ចន្លោះណាខាងក្រោម ដែលអនុគមន៍ \(f(x)=\dfrac{x+3}{x-1}\) ជាប់ ?', NULL, '["\\((1,+\\infty)\\)", "\\((-\\infty,1]\\)", "\\((0,3)\\)", "\\([0,2]\\)"]', 0, NULL, 2, 'mcq', '\(f\) ជាអនុគមន៍សនិទាន មិនកំណត់ត្រង់ \(x=1\) ដូច្នេះជាប់លើ \((-\infty,1)\) និង \((1,+\infty)\) ។ ចន្លោះផ្សេងទៀតមានចំណុច \(1\)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30215, 'ចន្លោះណាមួយដែលប្រាកដថាមានឫសនៃសមីការ \(x^3-x-1=0\) ?', NULL, '["\\([1,2]\\)", "\\([0,1]\\)", "\\([-1,0]\\)", "\\([2,3]\\)"]', 0, NULL, 2, 'mcq', '\(f(1)=-1<0\) ហើយ \(f(2)=5>0\) ដូច្នេះមានឫសក្នុង \((1,2)\)។ ឯ \([-1,0]\), \([0,1]\) ទាំងពីរបាត់ជាអវិជ្ជមាន ហើយ \([2,3]\) ទាំងពីរវិជ្ជមាន។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30216, 'អនុគមន៍ \(f(x)=\dfrac{x-1}{x^2-1}\) ដាច់ត្រង់ចំនួនចំណុចប៉ុន្មាន ?', NULL, '["\\(1\\)", "\\(0\\)", "\\(2\\)", "\\(3\\)"]', 2, NULL, 2, 'mcq', '\(x^2-1=0\) គឺ \(x=\pm1\) ។ ចំណុចទាំងពីរ \(f\) មិនកំណត់ ដូច្នេះដាច់ត្រង់ \(2\) ចំណុច (ត្រង់ \(x=1\) ជាចំណុចដាច់អាចបន្ថាយបាន)។', 'លក្ខណៈនៃអនុគមន៍ជាប់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30217, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} a + 3 x & \text{បើ } x<2 \\ x^{2} - 1 & \text{បើ } x\ge2 \end{cases}\) ជាប់ចំពោះគ្រប់ចំនួនពិត \(x\)។', NULL, '["\\(a=3\\)", "\\(a=9\\)", "\\(a=-3\\)", "\\(a=-6\\)"]', 2, NULL, 2, 'mcq', 'ជាប់ត្រង់ \(x=2\) ៖ \(6+a=2^2-1=3\) គឺ \(a=-3\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30218, 'រកតម្លៃ \(k\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{\sin{\left(2 x \right)}}{x} & \text{បើ } x\ne0 \\ k & \text{បើ } x=0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(k=2\\)", "\\(k=1\\)", "\\(k=0\\)", "\\(k=\\dfrac12\\)"]', 0, NULL, 2, 'mcq', '\(\dfrac{\sin2x}{x}=2\cdot\dfrac{\sin2x}{2x}\to2\) ដូច្នេះត្រូវ \(k=2\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30219, 'អនុគមន៍ \(f(x)=\sqrt{\dfrac{x-1}{x+3}}\) ជាប់លើចន្លោះណា ?', NULL, '["\\((-3,1]\\)", "\\([1,+\\infty)\\)", "\\((-\\infty,-3]\\cup[1,+\\infty)\\)", "\\((-\\infty,-3)\\cup[1,+\\infty)\\)"]', 3, NULL, 2, 'mcq', '\(\dfrac{x-1}{x+3}\ge0\) គឺ \(x<-3\) ឬ \(x\ge1\) ហើយអនុគមន៍បណ្ដាក់ជាប់លើដែនកំណត់នេះ។ (\(x=-3\) មិនកំណត់)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30220, 'ចន្លោះណាមួយដែលសមីការ \(e^x+x=3\) ប្រាកដថាមានឫស ?', NULL, '["\\([1,2]\\)", "\\([2,3]\\)", "\\([-1,0]\\)", "\\([0,1]\\)"]', 3, NULL, 2, 'mcq', 'តាង \(f(x)=e^x+x-3\) ៖ \(f(0)=-2<0\) និង \(f(1)=e-2\approx0{,}72>0\)។ ឯចន្លោះផ្សេងមិនប្ដូរសញ្ញាទេ។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30221, 'រកតម្លៃ \(k\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{1 - \cos{\left(x \right)}}{x^{2}} & \text{បើ } x\ne0 \\ k & \text{បើ } x=0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '["\\(k=2\\)", "\\(k=\\dfrac12\\)", "\\(k=0\\)", "\\(k=1\\)"]', 1, NULL, 2, 'mcq', '\(1-\cos x=2\sin^2\tfrac x2\) ដូច្នេះ \(\dfrac{1-\cos x}{x^2}\to\dfrac12\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30222, 'អនុគមន៍មួយណាខាងក្រោម ជាប់ចំពោះគ្រប់ចំនួនពិត ?', NULL, '["\\(f(x)=\\tan x\\)", "\\(f(x)=|x^2-4|\\)", "\\(f(x)=\\sqrt{x-4}\\)", "\\(f(x)=\\dfrac{1}{x^2-4}\\)"]', 1, NULL, 2, 'mcq', '\(x^2-4\) ជាប់ ហើយ \(|\cdot|\) ជាប់ ដូច្នេះអនុគមន៍បណ្ដាក់ជាប់ \(\mathbb{R}\)។ ឯផ្សេងទៀតមិនកំណត់ត្រង់ចំណុចខ្លះ។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30223, 'សមីការ \(x^3+x=5\) មានឫសប៉ុន្មានក្នុងចន្លោះ \([1,2]\) ?', NULL, '["គ្មាន", "បី", "មួយ", "ពីរ"]', 2, NULL, 2, 'mcq', 'តាង \(f(x)=x^3+x\) ជាប់និងកើនដាច់ខាត \(f(1)=2<5<10=f(2)\) ដូច្នេះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាលនិងវិបាក មានឫសមួយគត់។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30224, 'គណនា \(\lim_{x\to 2}\sqrt{x^{2} + x - 1}\)។', NULL, '["\\(5\\)", "\\(\\sqrt{5}\\)", "\\(\\sqrt{3}\\)", "\\(2\\)"]', 1, NULL, 2, 'mcq', '\(x^2+x-1\to5\) ហើយ \(\sqrt\cdot\) ជាប់ត្រង់ \(5\) ដូច្នេះ \(\sqrt5\)។', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30225, 'រកតម្លៃ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} 2 x + 3 & \text{បើ } x<-1 \\ a x + b & \text{បើ } -1\le x\le2 \\ x^{2} & \text{បើ } x>2 \end{cases}\) ជាប់លើ \(\mathbb{R}\)។', NULL, '["\\(a=1,\\ b=2\\)", "\\(a=3,\\ b=0\\)", "\\(a=2,\\ b=1\\)", "\\(a=1,\\ b=3\\)"]', 0, NULL, 3, 'mcq', 'ត្រង់ \(x=-1\) ៖ \(2(-1)+3=1=-a+b\) ។ ត្រង់ \(x=2\) ៖ \(2a+b=2^2=4\)។ ដកគ្នា \(3a=3\) គឺ \(a=1\) ហើយ \(b=2\)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30226, 'ចន្លោះណាមួយដែលសមីការ \(\cos x=x\) ប្រាកដថាមានឫស ?', NULL, '["\\([2,3]\\)", "\\([0,1]\\)", "\\([-2,-1]\\)", "\\([1,2]\\)"]', 1, NULL, 3, 'mcq', 'តាង \(f(x)=\cos x-x\) ៖ \(f(0)=1>0\) និង \(f(1)=\cos1-1\approx-0{,}46<0\)។ ឯ \([1,2]\), \([2,3]\) \(f\) អវិជ្ជមានទាំងពីរ ហើយ \([-2,-1]\) \(f\) វិជ្ជមានទាំងពីរ។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30227, 'កំណត់ \(g(0)\) ដែលធ្វើឱ្យ \(g(x)=\dfrac{\sqrt{1+x}-1}{x}\) ជាបន្ថាយជាប់ត្រង់ \(0\) ដោយគណនា \(\lim_{x\to 0}\dfrac{\sqrt{x + 1} - 1}{x}\)។', NULL, '["\\(2\\)", "\\(0\\)", "\\(\\dfrac{1}{2}\\)", "\\(1\\)"]', 2, NULL, 3, 'mcq', 'គុណអនុញ្ញាតិរួម ៖ \(\dfrac{x}{x(\sqrt{1+x}+1)}=\dfrac1{\sqrt{1+x}+1}\to\dfrac12\) ដូច្នេះ \(g(0)=\dfrac12\)។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30228, 'គេមាន \(f(x)=\begin{cases} x \sin{\left(\dfrac{1}{x} \right)} & \text{បើ } x\ne0 \\ 0 & \text{បើ } x=0 \end{cases}\)។ ការអះអាងមួយណាត្រឹមត្រូវ ?', NULL, '["\\(f\\) ដាច់ត្រង់ \\(0\\) ព្រោះ \\(f(0)\\) មិនកំណត់", "\\(f\\) ជាប់ត្រង់ \\(0\\) ព្រោះ \\(|x\\sin\\tfrac1x|\\le|x|\\to0=f(0)\\)", "\\(f\\) ដាច់ត្រង់ \\(0\\) ព្រោះ \\(\\sin\\tfrac1x\\) មិនមានលីមីត", "\\(f\\) ជាប់ត្រង់ \\(0\\) ព្រោះ \\(\\tfrac1x\\to\\infty\\)"]', 1, NULL, 3, 'mcq', 'ទ្រឹស្ដីបទកៀប ៖ \(-|x|\le x\sin\tfrac1x\le|x|\) ដូច្នេះលីមី \(=0=f(0)\) (ទោះ \(\sin\tfrac1x\) គ្មានលីមីត)។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30229, 'ការអះអាងមួយណាត្រឹមត្រូវ ចំពោះ \(f(x)=\dfrac1x\) លើ \([-1,1]\) ?', NULL, '["មិនអាចប្រើទ្រឹស្ដីបទតម្លៃកណ្ដាលបាន ព្រោះ \\(f\\) មិនជាប់ត្រង់ \\(x=0\\)", "\\(f(c)=0\\) មានឫសពីរក្នុង \\((-1,1)\\)", "មាន \\(c\\in(-1,1)\\) ដែល \\(f(c)=0\\) ព្រោះ \\(f(-1)<0<f(1)\\)", "\\(f\\) ជាប់លើ \\([-1,1]\\) ព្រោះជាអនុគមន៍សនិទាន"]', 0, NULL, 3, 'mcq', '\(f(-1)=-1<0<1=f(1)\) តែ \(f\) មិនកំណត់ត្រង់ \(0\) ដូច្នេះលក្ខខណ្ឌ "ជាប់លើ \([-1,1]\)" មិនពិត ហើយ \(\dfrac1x\ne0\) គ្រប់ \(x\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30230, 'គេមាន \(f(x)=\begin{cases} \dfrac{a x + b + x^{2}}{x - 1} & \text{បើ } x\ne1 \\ 3 & \text{បើ } x=1 \end{cases}\) ជាប់ត្រង់ \(x=1\)។ តម្លៃ \(a+b\) ស្មើនឹង ៖', NULL, '["\\(1\\)", "\\(-3\\)", "\\(-1\\)", "\\(3\\)"]', 2, NULL, 3, 'mcq', 'ភាគយកត្រូវសូន្យត្រង់ \(1\) ៖ \(1+a+b=0\) គឺ \(a+b=-1\) (ហើយ \(\dfrac{(x-1)(x+1+a)}{x-1}\to2+a=3\) នាំឱ្យ \(a=1,\ b=-2\))។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30231, 'ដោយគណនា \(f(x)=x^3-3x+1\) ត្រង់ \(x=-2,-1,0,1,2\) តើទ្រឹស្ដីបទតម្លៃកណ្ដាលធានាបានថាសមីការ \(f(x)=0\) មានឫសយ៉ាងតិចប៉ុន្មាននៅក្នុង \((-2,2)\) ?', NULL, '["\\(4\\)", "\\(1\\)", "\\(2\\)", "\\(3\\)"]', 3, NULL, 3, 'mcq', '\(f(-2)=-1,\ f(-1)=3,\ f(0)=1,\ f(1)=-1,\ f(2)=3\) ។ សញ្ញាប្ដូរក្នុង \((-2,-1)\), \((0,1)\), \((1,2)\) ដូច្នេះមានឫសយ៉ាងតិច \(3\) (ហើយពហុធាដឺក្រេ \(3\) មិនលើស \(3\))។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
