INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30232, 'ក្រុមហ៊ុនអគ្គិសនីគិតថ្លៃ \(C(x)\) (ដុល្លារ) តាមអំពើប្រើ \(x\) kWh ដោយ \(C(x)=\begin{cases} \dfrac{3 x}{20} & \text{បើ } 0\le x\le200 \\ m + \dfrac{x}{10} - 20 & \text{បើ } x>200 \end{cases}\) ។ ដើម្បីកុំឱ្យក្រាបថ្លៃមានការលោត (ជាប់ត្រង់ \(x=200\)) ត្រូវយក \(m\) ស្មើនឹងប៉ុន្មាន ដូចក្នុងរូប ?', 'g12sc-7c300c718d.svg', '["\\(0{,}15\\)", "\\(15\\)", "\\(20\\)", "\\(30\\)"]', 3, NULL, 3, 'mcq', 'ជាប់ត្រង់ \(200\) ៖ \(m+0=0{,}15\times200=30\) ដូច្នេះ \(m=30\) ដុល្លារ។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-4ecfbfb04d.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30233, 'សីតុណ្ហភាពក្នុងឡមួយ \(T(t)\) (°C) ក្រោយ \(t\) ម៉ោង ត្រូវបានកត់ត្រាដូចក្នុងរូប ។ ក្រាបមិនជាប់ត្រង់ \(t=4\)។ តើតម្លៃសីតុណ្ហភាព "លោត" ប៉ុន្មានដឺក្រេ ត្រង់ \(t=4\) ?', 'g12sc-4ecfbfb04d.svg', '["\\(23\\) °C", "\\(4\\) °C", "\\(18\\) °C", "\\(5\\) °C"]', 3, NULL, 3, 'mcq', 'ខាងឆ្វេង \(\lim_{t\to4^-}T=18\) ហើយ \(T(4)=\lim_{t\to4^+}T=23\) ដូច្នេះលោត \(23-18=5\) °C។', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-1c1757519c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30234, 'អ្នកដើរភ្នំម្នាក់ចាប់ផ្ដើមនៅកម្ពស់ \(120\ \text{m}\) ហើយទៅដល់កម្ពស់ \(480\ \text{m}\) ក្រោយ \(6\) ម៉ោង តាមផ្លូវជាប់ ដូចក្នុងរូប ។ ហេតុអ្វីបានជាប្រាកដថាអ្នកដើរភ្នំនោះនៅកម្ពស់ \(300\ \text{m}\) យ៉ាងតិចម្ដង ?', 'g12sc-1c1757519c.svg', '["លីមីតអនន្ត ព្រោះគ្មានទីបញ្ចប់", "ទ្រឹស្ដីបទតម្លៃកណ្ដាល ព្រោះកម្ពស់ជាអនុគមន៍ជាប់នៃពេល", "ទ្រឹស្ដីបទពីតាគ័រ", "ទ្រឹស្ដីបទកៀប ព្រោះកម្ពស់ចងដោយតម្លៃពីរ"]', 1, NULL, 3, 'mcq', 'កម្ពស់ \(h(t)\) ជាអនុគមន៍ជាប់លើ \([0,6]\) និង \(h(0)=120<300<480=h(6)\) ដូច្នេះមាន \(t\in(0,6)\) ដែល \(h(t)=300\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Understand');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-87d7694073.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30235, 'វិស្វករម្នាក់ដោះស្រាយ \(f(x)=x^3-2x-5=0\) ដោយដឹងថា \(f(2)=-1\) និង \(f(3)=16\) ដូចក្នុងរូប ។ ក្រោយគណនាចំណុចកណ្ដាល \(2{,}5\) ដែល \(f(2{,}5)\approx5{,}6>0\) តើឫសស្ថិតក្នុងចន្លោះណា ?', 'g12sc-87d7694073.svg', '["\\((0;\\ 2)\\)", "\\((3;\\ 4)\\)", "\\((2;\\ 2{,}5)\\)", "\\((2{,}5;\\ 3)\\)"]', 2, NULL, 3, 'mcq', '\(f(2)<0<f(2{,}5)\) ហើយ \(f\) ជាប់ ដូច្នេះឫសនៅក្នុង \((2;\ 2{,}5)\)។', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30236, 'ឧបករណ៍វាស់មួយបង្ហាញតម្លៃ \(R(t)=\dfrac{\sin t}{t}\) ចំពោះ \(t\ne0\) ហើយមិនមានតម្លៃត្រង់ \(t=0\) (រូបបង្ហាញក្រាបមានប្រហោង) ។ ដើម្បីឱ្យក្រាបជាប់ ត្រូវកំណត់ \(R(0)\) ស្មើនឹងប៉ុន្មាន ?', 'g12sc-cdbeb7c56e.svg', '["\\(1\\)", "\\(\\pi\\)", "\\(0\\)", "\\(\\dfrac12\\)"]', 0, NULL, 3, 'mcq', '\(\displaystyle\lim_{t\to0}\dfrac{\sin t}{t}=1\) ដូច្នេះត្រូវយក \(R(0)=1\) ដើម្បីបន្ថាយតាមភាពជាប់។', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'pisa', 1, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30237, 'សិក្សាភាពជាប់ត្រង់ \(x=1\) នៃអនុគមន៍ \(f(x)=\begin{cases} 2 x - 1 & \text{បើ } x\le1 \\ x^{2} & \text{បើ } x>1 \end{cases}\)។', NULL, '[]', 0, NULL, 5, 'writing', 'លក្ខខណ្ឌទី ១ ៖ \(f(1)=2(1)-1=1\) ដូច្នេះ \(f\) កំណត់ត្រង់ \(1\) (1 ពិន្ទុ)
លីមីតខាងឆ្វេង ៖ \(\displaystyle\lim_{x\to1^-}(2x-1)=1\) (1 ពិន្ទុ)
លីមីតខាងស្ដាំ ៖ \(\displaystyle\lim_{x\to1^+}x^2=1\) (1 ពិន្ទុ)
លីមីតទាំងពីរស្មើគ្នា ដូច្នេះ \(\displaystyle\lim_{x\to1}f(x)=1\) មាន (1 ពិន្ទុ)
\(\displaystyle\lim_{x\to1}f(x)=1=f(1)\) ដូច្នេះ \(f\) ជាប់ត្រង់ \(x=1\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'easy', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30238, 'រកតម្លៃ \(a\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{x^{2} - 5 x + 6}{x - 2} & \text{បើ } x\ne2 \\ a & \text{បើ } x=2 \end{cases}\) ជាប់ត្រង់ \(x=2\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ជាប់ត្រង់ \(2\) លុះត្រាតែ \(\displaystyle\lim_{x\to2}f(x)=f(2)=a\) (1 ពិន្ទុ)
ចំពោះ \(x\ne2\) ៖ \(x^2-5x+6=(x-2)(x-3)\) (1 ពិន្ទុ)
សម្រួល ៖ \(\dfrac{(x-2)(x-3)}{x-2}=x-3\) (1 ពិន្ទុ)
លីមីត ៖ \(\displaystyle\lim_{x\to2}(x-3)=-1\) (1 ពិន្ទុ)
ដូច្នេះ \(a=-1\) (ជាអនុគមន៍បន្ថាយជាប់នៃ \(x-3\))។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'medium', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30239, 'កំណត់ចន្លោះដែលអនុគមន៍ \(f(x)=\sqrt{\dfrac{x-3}{x+2}}\) ជាប់ ។', NULL, '[]', 0, NULL, 5, 'writing', 'ដែនកំណត់ ៖ \(\dfrac{x-3}{x+2}\ge0\) និង \(x\ne-2\) (1 ពិន្ទុ)
តារាងសញ្ញា ៖ \(x-3\) សូន្យត្រង់ \(3\) ; \(x+2\) សូន្យត្រង់ \(-2\) (1 ពិន្ទុ)
ប្រភាគវិជ្ជមាន (ឬសូន្យ) កាលណា \(x<-2\) ឬ \(x\ge3\) (1 ពិន្ទុ)
ប្រភាគ \(\dfrac{x-3}{x+2}\) ជាប់ ហើយ \(\sqrt{\cdot}\) ជាប់ ដូច្នេះអនុគមន៍បណ្ដាក់ជាប់លើដែនកំណត់ (1 ពិន្ទុ)
សន្និដ្ឋាន ៖ \(f\) ជាប់លើ \((-\infty,-2)\cup[3,+\infty)\) (ត្រង់ \(3\) ជាប់ខាងស្ដាំ)។ (1 ពិន្ទុ)', 'ភាពជាប់លើចន្លោះ និងអនុគមន៍បណ្ដាក់', 'medium', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30240, 'ក. បង្ហាញថាសមីការ \(x^3+x-1=0\) មានឫសក្នុងចន្លោះ \((0,1)\)។ ខ. បង្ហាញថាមានឫសតែមួយគត់ក្នុងចន្លោះនេះ។', NULL, '[]', 0, NULL, 5, 'writing', 'តាង \(f(x)=x^3+x-1\) ជាអនុគមន៍ពហុធា ដូច្នេះជាប់លើ \([0,1]\) (1 ពិន្ទុ)
\(f(0)=-1<0\) និង \(f(1)=1+1-1=1>0\) (1 ពិន្ទុ)
ទ្រឹស្ដីបទតម្លៃកណ្ដាល ៖ មាន \(c\in(0,1)\) ដែល \(f(c)=0\) (1 ពិន្ទុ)
ខ. បើ \(0\le u<v\le1\) នោះ \(u^3<v^3\) និង \(u<v\) ដូច្នេះ \(f(u)<f(v)\) គឺ \(f\) កើនដាច់ខាត (1 ពិន្ទុ)
តាមវិបាក សមីការ \(f(x)=0\) មានចម្លើយតែមួយគត់ក្នុង \((0,1)\)។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'medium', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30241, 'កំណត់ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} \dfrac{\sin{\left(3 x \right)}}{x} & \text{បើ } x<0 \\ a & \text{បើ } x=0 \\ \dfrac{e^{b x} - 1}{x} & \text{បើ } x>0 \end{cases}\) ជាប់ត្រង់ \(x=0\)។', NULL, '[]', 0, NULL, 5, 'writing', 'ខាងឆ្វេង ៖ \(\displaystyle\lim_{x\to0^-}\dfrac{\sin3x}{x}=3\lim\dfrac{\sin3x}{3x}=3\) (1 ពិន្ទុ)
ខាងស្ដាំ ៖ \(\displaystyle\lim_{x\to0^+}\dfrac{e^{bx}-1}{x}=b\lim\dfrac{e^{bx}-1}{bx}=b\) (បើ \(b\ne0\)) (1 ពិន្ទុ)
លក្ខខណ្ឌជាប់ ៖ \(3=f(0)=a=b\) (1 ពិន្ទុ)
ដូច្នេះ \(a=3\) និង \(b=3\) (1 ពិន្ទុ)
ផ្ទៀងផ្ទាត់ ៖ \(b=0\) ឱ្យ \(f(x)=0\to0\ne3\) មិនបាន ដូច្នេះចម្លើយតែមួយគត់ \(a=b=3\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'medium', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30242, 'កំណត់ \(a\) និង \(b\) ដើម្បីឱ្យ \(f(x)=\begin{cases} 2 x + 3 & \text{បើ } x<-1 \\ a x + b & \text{បើ } -1\le x\le2 \\ x^{2} & \text{បើ } x>2 \end{cases}\) ជាប់ចំពោះគ្រប់ចំនួនពិត ។', NULL, '[]', 0, NULL, 5, 'writing', 'ពហុធានីមួយៗជាប់លើចន្លោះបើករបស់វា ដូច្នេះត្រូវពិនិត្យតែចំណុចភ្ជាប់ \(x=-1\) និង \(x=2\) (1 ពិន្ទុ)
ត្រង់ \(x=-1\) ៖ \(\displaystyle\lim_{x\to-1^-}(2x+3)=1\) និង \(f(-1)=-a+b\) (1 ពិន្ទុ)
សមីការទី ១ ៖ \(-a+b=1\) (1 ពិន្ទុ)
ត្រង់ \(x=2\) ៖ \(f(2)=2a+b\) និង \(\displaystyle\lim_{x\to2^+}x^2=4\) ដូច្នេះ \(2a+b=4\) (1 ពិន្ទុ)
ដោះស្រាយប្រព័ន្ធ ៖ ដកគ្នា \(3a=3\) ដូច្នេះ \(a=1\) ហើយ \(b=2\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'hard', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-6ca596abe6.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30243, 'គេមាន \(f(x)=\begin{cases} x \sin{\left(\dfrac{1}{x} \right)} & \text{បើ } x\ne0 \\ 1 & \text{បើ } x=0 \end{cases}\) (រូបបង្ហាញក្រាបនៃ \(y=x\sin\tfrac1x\) ចន្លោះបន្ទាត់ \(y=\pm x\)) ។ ក. ប្រើទ្រឹស្ដីបទកៀបរក \(\displaystyle\lim_{x\to0}f(x)\) ។ ខ. តើ \(f\) ជាប់ត្រង់ \(0\) ឬទេ ? គ. ត្រូវកែ \(f(0)\) ជាប៉ុន្មានដើម្បីឱ្យជាប់ ?', 'g12sc-6ca596abe6.svg', '[]', 0, NULL, 5, 'writing', 'សម្រាប់ \(x\ne0\) ៖ \(-1\le\sin\tfrac1x\le1\) (1 ពិន្ទុ)
គុណនឹង \(|x|\) ៖ \(-|x|\le x\sin\tfrac1x\le|x|\) (ព្រោះ \(|x\sin\tfrac1x|\le|x|\)) (1 ពិន្ទុ)
ដោយ \(\displaystyle\lim_{x\to0}|x|=0\) តាមទ្រឹស្ដីបទកៀប \(\displaystyle\lim_{x\to0}x\sin\tfrac1x=0\) (1 ពិន្ទុ)
ខ. \(f(0)=1\ne0=\lim f(x)\) ដូច្នេះ \(f\) មិនជាប់ត្រង់ \(0\) (ដាច់អាចបន្ថាយបាន) (1 ពិន្ទុ)
គ. ត្រូវកែ \(f(0)=0\) ដើម្បីឱ្យ \(\lim_{x\to0}f(x)=f(0)\) ហើយ \(f\) ជាប់ត្រង់ \(0\)។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'hard', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-26656a1871.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30244, 'ក្រាបនៃអនុគមន៍ជាប់ \(f:[0,1]\to[0,1]\) ត្រូវបានបង្ហាញក្នុងរូបជាមួយបន្ទាត់ \(y=x\) ។ បង្ហាញថាមាន \(c\in[0,1]\) ដែល \(f(c)=c\) (ចំណុចថេរ)។', 'g12sc-26656a1871.svg', '[]', 0, NULL, 5, 'writing', 'តាង \(g(x)=f(x)-x\) ជាប់លើ \([0,1]\) (ផលដកនៃអនុគមន៍ជាប់) (1 ពិន្ទុ)
ដោយ \(f(0)\in[0,1]\) នោះ \(g(0)=f(0)-0\ge0\) (1 ពិន្ទុ)
ដោយ \(f(1)\in[0,1]\) នោះ \(g(1)=f(1)-1\le0\) (1 ពិន្ទុ)
បើ \(g(0)=0\) ឬ \(g(1)=0\) នោះ \(c=0\) ឬ \(c=1\) ជាចំណុចថេរ (1 ពិន្ទុ)
បើមិនដូច្នេះ \(g(0)>0>g(1)\) តាមទ្រឹស្ដីបទតម្លៃកណ្ដាលមាន \(c\in(0,1)\) ដែល \(g(c)=0\) គឺ \(f(c)=c\)។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Create');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-a2179fe74c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30245, 'បង្ហាញថាសមីការ \(x^4-4x-1=0\) មានឫសពិតយ៉ាងតិចពីរ (ដូចរូប) ដោយប្រើទ្រឹស្ដីបទតម្លៃកណ្ដាល ហើយរកចន្លោះប្រវែង \(1\) ដែលមានឫសនីមួយៗ ។', 'g12sc-a2179fe74c.svg', '[]', 0, NULL, 5, 'writing', 'តាង \(f(x)=x^4-4x-1\) ជាពហុធា ដូច្នេះជាប់លើ \(\mathbb{R}\) (1 ពិន្ទុ)
គណនា ៖ \(f(-1)=1+4-1=4>0\) និង \(f(0)=-1<0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(-1)f(0)<0\) មានឫសមួយក្នុង \((-1,0)\) (1 ពិន្ទុ)
គណនា ៖ \(f(1)=1-4-1=-4<0\) និង \(f(2)=16-8-1=7>0\) (1 ពិន្ទុ)
ដូច្នេះ \(f(1)f(2)<0\) មានឫសមួយទៀតក្នុង \((1,2)\) ហើយចន្លោះទាំងពីរមិនប៉ះគ្នា ដូច្នេះឫសខុសគ្នា។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'hard', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-064b62794c.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30246, 'ក្រុមហ៊ុនទូរសព្ទគិតថ្លៃ \(C(x)\) (ដុល្លារ) តាមបរិមាណទិន្នន័យ \(x\) GB ដោយ \(C(x)=\begin{cases} \dfrac{x}{4} & \text{បើ } 0\le x\le80 \\ m + \dfrac{3 x}{20} - 12 & \text{បើ } x>80 \end{cases}\) ដូចក្នុងរូប ។ ក. រក \(m\) ដើម្បីកុំឱ្យថ្លៃលោត ត្រង់ \(x=80\)។ ខ. គណនា \(C(200)\)។ គ. ប្រៀបធៀបថ្លៃមធ្យមក្នុង ១ GB ត្រង់ \(x=200\) និង \(x=80\)។', 'g12sc-064b62794c.svg', '[]', 0, NULL, 5, 'writing', 'ក. ជាប់ត្រង់ \(80\) ៖ \(\displaystyle\lim_{x\to80^-}C=\dfrac14\cdot80=20\) និង \(C(80^+)=m+0=m\) (1 ពិន្ទុ)
ដូច្នេះ \(m=20\) ដុល្លារ (1 ពិន្ទុ)
ខ. \(C(200)=20+0{,}15(200-80)=20+18=38\) ដុល្លារ (1 ពិន្ទុ)
គ. ថ្លៃមធ្យមត្រង់ \(80\) ៖ \(\dfrac{20}{80}=0{,}25\) ដុល្លារ/GB (1 ពិន្ទុ)
ត្រង់ \(200\) ៖ \(\dfrac{38}{200}=0{,}19\) ដុល្លារ/GB ទាបជាង ព្រោះអត្រាក្រោយ \(80\) ថោកជាង \(0{,}15<0{,}25\)។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-7cbbfa0a35.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30247, 'ចំណតរថយន្តគិតថ្លៃ \(P(t)\) (ដុល្លារ) ដោយ \(2\) ដុល្លារ សម្រាប់ម៉ោងទី ១ (\(0<t\le1\)) \(4\) ដុល្លារ សម្រាប់ \(1<t\le2\) \(6\) ដុល្លារ សម្រាប់ \(2<t\le3\) ដូចក្នុងរូប ។ ក. រក \(\displaystyle\lim_{t\to2^-}P(t)\) និង \(\displaystyle\lim_{t\to2^+}P(t)\) ។ ខ. តើ \(P\) ជាប់ត្រង់ \(t=2\) ឬទេ ? គ. តើ \(P\) ជាប់ខាងឆ្វេង ឬខាងស្ដាំត្រង់ \(t=2\) ?', 'g12sc-7cbbfa0a35.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(P(2)=4\) (ព្រោះ \(1<2\le2\)) \(\displaystyle\lim_{t\to2^-}P(t)=4\) (1 ពិន្ទុ)
\(\displaystyle\lim_{t\to2^+}P(t)=6\) (ព្រោះ \(2<t\le3\)) (1 ពិន្ទុ)
ខ. លីមីតខាងឆ្វេង \(4\ne6\) លីមីតខាងស្ដាំ ដូច្នេះ \(\lim_{t\to2}P(t)\) មិនមាន (1 ពិន្ទុ)
ដូច្នេះ \(P\) មិនជាប់ត្រង់ \(t=2\) (លោត \(6-4=2\) ដុល្លារ) (1 ពិន្ទុ)
គ. \(\lim_{t\to2^-}P=4=P(2)\) ដូច្នេះជាប់ខាងឆ្វេង ប៉ុន្តែមិនជាប់ខាងស្ដាំ។ (1 ពិន្ទុ)', 'និយមន័យ និងភាពជាប់ត្រង់មួយចំណុច', 'pisa', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Analyze');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-2e4030e1c2.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30248, 'សីតុណ្ហភាពបន្ទប់មួយ \(T(t)=-0{,}25(t-14)^2+27\) (°C) ចំពោះ \(6\le t\le14\) ដូចក្នុងរូប ។ ក. គណនា \(T(6)\) និង \(T(14)\)។ ខ. ពន្យល់ថាហេតុអ្វីមានពេលមួយដែល \(T=20\) °C ។ គ. រកពេលនោះ។', 'g12sc-2e4030e1c2.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(T(6)=-0{,}25(64)+27=11\) °C (1 ពិន្ទុ)
\(T(14)=-0{,}25(0)+27=27\) °C (1 ពិន្ទុ)
ខ. \(T\) ជាពហុធា ដូច្នេះជាប់លើ \([6,14]\) ហើយ \(T(6)=11<20<27=T(14)\) ដូច្នេះតាមទ្រឹស្ដីបទតម្លៃកណ្ដាលមាន \(t\in(6,14)\) ដែល \(T(t)=20\) (1 ពិន្ទុ)
គ. \(-0{,}25(t-14)^2+27=20\) គឺ \((t-14)^2=28\) (1 ពិន្ទុ)
ដូច្នេះ \(t=14\pm2\sqrt7\) ; ដោយ \(t\le14\) បាន \(t=14-2\sqrt7\approx8{,}71\) ម៉ោង (ក្នុង \((6,14)\))។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Apply');
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30249, 'អ្នកគណនាចង់រកឫសនៃ \(f(x)=x^3-2x-5\) ដោយវិធីពុះពាក់កណ្ដាលចន្លោះ ចាប់ពី \([2,3]\) ដូចក្នុងរូប ។ ក. បង្ហាញថាមានឫសក្នុង \((2,3)\) ។ ខ. ធ្វើជំហានពុះបីដង រួចរកចន្លោះប្រវែង \(0{,}125\) ដែលមានឫស ។ គ. ពន្យល់ថាហេតុអ្វីត្រូវការភាពជាប់។', 'g12sc-87d7694073.svg', '[]', 0, NULL, 5, 'writing', 'ក. \(f(2)=8-4-5=-1<0\) និង \(f(3)=27-6-5=16>0\) ហើយ \(f\) ជាប់ ដូច្នេះមានឫសក្នុង \((2,3)\) (1 ពិន្ទុ)
ខ. ជំហានទី ១ ៖ ចំណុចកណ្ដាល \(2{,}5\) \(f(2{,}5)=15{,}625-5-5=5{,}625>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}5)\) (1 ពិន្ទុ)
ជំហានទី ២ ៖ \(f(2{,}25)=11{,}390\,625-4{,}5-5=1{,}890\,625>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}25)\) (1 ពិន្ទុ)
ជំហានទី ៣ ៖ \(f(2{,}125)=9{,}595\,703-4{,}25-5=0{,}345\,703>0\) ដូច្នេះឫសក្នុង \((2;\ 2{,}125)\) ប្រវែង \(0{,}125\) (1 ពិន្ទុ)
គ. បើ \(f\) មិនជាប់ អាចលោតពីអវិជ្ជមានទៅវិជ្ជមានដោយមិនកាត់សូន្យ ដូច្នេះទ្រឹស្ដីបទតម្លៃកណ្ដាលមិនធានាឫស ; ឫសពិតប្រាកដ \(\approx2{,}0\,946\) នៅក្នុងចន្លោះចុងក្រោយ។ (1 ពិន្ទុ)', 'ទ្រឹស្ដីបទតម្លៃកណ្ដាល', 'pisa', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
INSERT OR REPLACE INTO images (key, content_type, data_base64, created_at) VALUES ('g12sc-7653bcae3e.svg', 'image/svg+xml', '', datetime('now'));
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled, bloom) VALUES (10, 30250, 'ឧបករណ៍មួយបង្ហាញតម្លៃ \(f(t)=\dfrac{1-\cos t}{t^2}\) ចំពោះ \(t\ne0\) ដោយ \(f(0)\) មិនទាន់កំណត់ ដូចក្នុងរូប ។ បច្ចេកទេសករម្នាក់ឱ្យ \(f(0)=0\) ។ ក. រក \(\displaystyle\lim_{t\to0}f(t)\) ។ ខ. វាយតម្លៃថា \(f(0)=0\) ត្រឹមត្រូវឬទេ ។ គ. កំណត់អនុគមន៍បន្ថាយតាមភាពជាប់ត្រង់ \(t=0\)។', 'g12sc-7653bcae3e.svg', '[]', 0, NULL, 5, 'writing', 'ក. ប្រើ \(1-\cos t=2\sin^2\tfrac t2\) ៖ \(f(t)=\dfrac{2\sin^2\frac t2}{t^2}\) (1 ពិន្ទុ)
សរសេរ \(f(t)=\dfrac12\left(\dfrac{\sin\frac t2}{\frac t2}\right)^2\) (ព្រោះ \(\left(\tfrac t2\right)^2=\tfrac{t^2}4\) ហើយ \(2\cdot\tfrac14=\tfrac12\)) (1 ពិន្ទុ)
ប្រើ \(\displaystyle\lim_{u\to0}\dfrac{\sin u}{u}=1\) ជាមួយ \(u=\tfrac t2\) ៖ \(\displaystyle\lim_{t\to0}f(t)=\dfrac12\cdot1=\dfrac12\) (1 ពិន្ទុ)
ខ. \(f(0)=0\ne\dfrac12\) ដូច្នេះ \(f\) នឹងមិនជាប់ត្រង់ \(0\) (ក្រាបមានលោត) ដូច្នេះការកំណត់របស់បច្ចេកទេសករមិនត្រឹមត្រូវ (1 ពិន្ទុ)
គ. \(g(t)=\begin{cases}\dfrac{1-\cos t}{t^2}&t\ne0\\\dfrac12&t=0\end{cases}\) ជាអនុគមន៍ជាប់ត្រង់ \(0\)។ (1 ពិន្ទុ)', 'អនុគមន៍បន្ថាយតាមភាពជាប់', 'pisa', 0, '12SS', 'ភាពជាប់នៃអនុគមន៍', 'ជំពូកទី 1 : លីមីត', NULL, 0, 'Evaluate');
